import{_ as i,l as n,o as e,c as o,v as t,p as s,x as l,d as h,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"基准饱和","description":"","frontmatter":{"title":"基准饱和","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/benchmark-saturation.md","filePath":"llm/benchmark-saturation.md","lastUpdated":1789023840000}'),m={name:"llm/benchmark-saturation.md"};function p(E,a,A,_,u,B){const r=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="基准饱和" tabindex="-1">基准饱和 <a class="header-anchor" href="#基准饱和" aria-label="Permalink to &quot;基准饱和&quot;">​</a></h1><div class="epigraph"><p>准确率靠近标注上限之后，剩余误差是歧义、过时事实与记忆，不是能力差。继续卷总分，信息量按噪声增长。</p><footer>—— 对照 [LiveBench](/llm/livebench) 的去饱和设计；Kiela 等 Dynabench 对静态榜的批评</footer></div><p><a href="/llm/eval-harness">上一课</a>把仪器冻住。冻住的公开卷会在数年内被做满。本课写饱和。缺口是：SOTA 表上的 0.5 分不再支持「更强」的声明。后课模型卡默认：接近天花板的基准应降级为回归测试，而不是主声明。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MMLU 一类四选一有标注错误与过时题。Gema 等对 MMLU 标注的审计说明：高分段的对错混进了金标噪声。模型越大越会拟合题解站，饱和与<a href="/llm/eval-contamination">污染</a>一起到来。这时平均准确率的方差主要来自题面争议，不是参数量。</p><p>第二条路是题太容易：随机基线 25%，从 85% 到 90% 与从 40% 到 45% 的含义不同。第三条路是产品任务已经换了（工具、长上下文、多轮），旧卷还在当门禁，选出「会考试的模型」。</p><p><span class="marginnote">饱和不是「基准无用」。它是「该基准对前沿模型的鉴别力下降」。对小模型与量化回归，同一卷往往仍有刻度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>诊断：看分位，不看均值。若多数模型挤在标注一致率附近，换更难的卷（GPQA、FrontierMath、LiveBench 月包）或换私有同分布集。动态基准靠时间戳抵抗记忆，但要版本化，见 <a href="/llm/livebench">LiveBench</a>。人评与 Arena 在开放任务上不饱和得那么快，但偏风格，后一单元再写。</p><p>发布策略：饱和卷改为「不得低于」门槛；主表换成仍有头尾差的卷。不要靠 decile 上的抖动发新闻稿。</p>',10)),(e(),s(d,null,{default:l(()=>[c(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20BENCH%5B%22%E5%85%AC%E5%BC%80%E9%9D%99%E6%80%81%E5%8D%B7%22%5D%20--%3E%20SAT%5B%22%E5%A4%B4%E9%83%A8%E9%98%9F%E5%88%97%E6%8C%A4%E6%89%81%22%5D%0A%20%20SAT%20--%3E%20HARD%5B%22%E6%9B%B4%E9%9A%BE%20%2F%20%E5%8A%A8%E6%80%81%20%2F%20%E7%A7%81%E6%9C%89%22%5D%0A%20%20SAT%20--%3E%20REG%5B%22%E9%99%8D%E7%BA%A7%E4%B8%BA%E5%9B%9E%E5%BD%92%E9%97%A8%E6%A7%9B%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>鉴别力来自误差的系统差。误差若被金标噪声主导，排名变成对噪声的过拟合。污染把「见过的题」从误差里删掉，进一步压扁头部。动态出题恢复误差，但引入窗口不可比；必须报 \\(\\mathrm{Acc}(M,W)\\)。私有集恢复鉴别力，牺牲外部复现——模型卡里要写清哪些声明可外部复核。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不点名「某某榜已死」。是否饱和取决于你比较的模型集合。下一课把「测了什么、没测什么、哪张榜已当回归」写进模型卡。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>接近标注上限后，总分差没有能力含义。</li><li>饱和卷改门槛，主声明换仍有鉴别力的仪器。</li><li>动态与私有补鉴别力，分别牺牲可比性与公开复现。</li><li>出处：Kiela 等 Dynabench；LiveBench；GPQA；MMLU 标注审计。</li></ul>',6))])}const T=i(m,[["render",p]]);export{b as __pageData,T as default};
